import Link from 'next/link'
import Image from 'next/image'
import { initContract, getEmoji } from '@/util/communication'
import GiftButton from '@/components/GiftButton'
import styles from './Page.module.scss'

export default async function Page() {
  const emoji = await getEmoji()
  const { web3, contract } = initContract()

  return (
    <div className={`${styles.page} ms-motion-slideDownIn mt-20`} data-width={`large`}>
      <div className={`__container`} data-width={`large`}>
        <div className={`${styles.grid} grid grid--fit w-100`} style={{ '--data-width': `100px` }}>
          {emoji && emoji.map((item, i) => {
            return (
              <div key={i} data-name={item.name} className={`${styles.emoji} d-flex flex-column align-items-center justify-content-between`}>
                <figure className={`${styles.emoji__icon}`}>
                  <Image
                    className={`animate__animated animate__heartBeat`}
                    src={`/emoji/${item.emoji}.svg`}
                    alt={`${process.env.NEXT_PUBLIC_NAME}`}
                    width={32}
                    height={32}
                    title={item.name}
                  />
                </figure>
                <div className={`w-100 d-flex flex-column grid--gap-050`}>
                  <small className={`text-center rounded`}>
                    <span>⏣ </span>
                    <span>{web3.utils.fromWei(item.price, `ether`)}</span>
                  </small>
                  <GiftButton emojiId={item.emojiId} />
                </div>
              </div>
            )
          })}
        </div>

        <LastGift/>
      </div>
    </div>
  )
}
